Solution A: function generateMaze(canvasID) {
    const canvas = document.getElementById(canvasID);
    const ctx = canvas.getContext('2d');
    const width = 500, height = 500;
    canvas.width = width;
    canvas.height = height;

    // Recursively divide cells to generate maze
    function divide(x, y, w, h) {
        if (w < 5 || h < 5) return;
        let nx = x + w, ny = y + h;
        if (Math.random() < 0.5) {
            if (w > h) {
                let dx = x + Math.floor(w / 2);
                ctx.moveTo(dx, y); ctx.lineTo(dx, ny); // Vertical line
                if (divide(x, y, w / 2, h) || divide(dx + 1, y, w - 2, h)) return true;
            } else {
                let dy = y + Math.floor(h / 2);
                ctx.moveTo(x, dy); ctx.lineTo(nx, dy); // Horizontal line
                if (divide(x, y, w, h / 2) || divide(x, dy + 1, w, h - 2)) return true;
            }
        }
        return false;
    }

    ctx.beginPath(); ctx.rect(0, 0, width, height); ctx.stroke();
    divide(1, 1, width - 2, height - 2);

    // A* search function to solve maze
    function astar(start, end) {
        let openSet = [start], cameFrom = {}, costSoFar = {}, heuristic = (a, b) => ((a[0] - b[0]) ** 2 + (a[1] - b[1]) ** 2) ** 0.5;
        costSoFar[start] = 0;
        while (openSet.length) {
            let current = openSet.pop();
            if (current[0] === end[0] && current[1] === end[1]) break;
            let neighbors = [[0, -1], [0, 1], [-1, 0], [1, 0]];
            for (let [dx, dy] of neighbors) {
                let next = [current[0] + dx, current[1] + dy];
                let nextCost = costSoFar[current] + 1;
                if (next[0] < 0 || next[0] >= width || next[1] < 0 || next[1] >= height || cell[next[0]][next[1]] !== 0) continue;
                if (costSoFar[next] === undefined || nextCost < costSoFar[next]) {
                    cameFrom[next] = current;
                    costSoFar[next] = nextCost;
                    openSet.push(next);
                }
            }
            ctx.fillStyle = '# Farbe für aktuellen Pfad';
            ctx.fillText(' ', [current[0] * 10, current[1] * 10]);
        }
        let totalPath = trace(cameFrom, start, end);
        ctx.fillStyle = '# Farbe für Lösung';
        for (let cell of totalPath) ctx.fillText(' ', [cell[0] * 10, cell[1] * 10]);
    }

    // Trace path backward from cameFrom map
    function trace(cameFrom, start, end) {
        let path = [end];
        while (path[0] !== start) { let p = cameFrom[path[0]]; path.unshift(p); }
        return path;
    }

    // Cell representation for A*
    let cell = Array.from({ length: width }, () => new Array(height).fill(0));
    for (let x = 0; x < width; x++) {
        for (let y = 0; y < height; y++) {
            if (!(x % 10) || !(y % 10)) cell[x][y] |= 2; // Walls
            if (x > 0 && x < width - 1 && y > 0 && y < height - 1 && cell[x][y] === 0) { // Path nodes
                let oneWay = Math.random() < 0.5 ? [[0, -1], [0, 1]] : [[-1, 0], [1, 0]];
                for (let [dx, dy] of oneWay) {
                    let nx = x + dx, ny = y + dy;
                    if (cell[nx][ny] === 2) {
                        cell[x][y] |= 1;
                        break;
                    }
                }
            }
        }
    }
    // Start and end points
    let start = [1, 1], end = [width - 2, height - 2];
    cell[start[0]][start[1]] = 3; // Start point
    cell[end[0]][end[1]] = 4; // End point

    // Draw cells
    for (let x = 0; x < width; x++) { for (let y = 0; y < height; y++) { ctx.fillStyle = '# Farbe für Celltyp ' + cell[x][y]; ctx.fillText(' ', [x * 10, y * 10]); } }
    astar(start, end); // Solve
}

Solution B: ```javascript
function generateAndSolveMaze(canvasId) {
    const canvas = document.getElementById(canvasId);
    if (!canvas) {
        console.error("Canvas not found");
        return;
    }
    const ctx = canvas.getContext('2d');
    const width = 500;
    const height = 500;
    const cellSize = 10;
    const cols = width / cellSize;
    const rows = height / cellSize;

    let maze = Array.from({ length: rows }, () => Array(cols).fill(0));
    let openSet = [];
    let closedSet = [];
    let startNode, endNode;

    function drawMaze() {
        for (let y = 0; y < rows; y++) {
            for (let x = 0; x < cols; x++) {
                if (maze[y][x] === 1) {
                    ctx.fillStyle = 'black';
                    ctx.fillRect(x * cellSize, y * cellSize, cellSize, cellSize);
                } else {
                    ctx.fillStyle = 'white';
                    ctx.fillRect(x * cellSize, y * cellSize, cellSize, cellSize);
                }
            }
        }
    }

    function recursiveDivision(x1, y1, x2, y2, horizontal) {
        if (horizontal) {
            if (y2 - y1 > 1) {
                const wallY = Math.floor(Math.random() * ((y2 - y1) / 2)) * 2 + y1 + 1;
                for (let x = x1; x <= x2; x++) {
                    maze[wallY][x] = 1;
                }
                recursiveDivision(x1, y1, x2, wallY, false);
                recursiveDivision(x1, wallY + 1, x2, y2, false);
            }
        } else {
            if (x2 - x1 > 1) {
                const wallX = Math.floor(Math.random() * ((x2 - x1) / 2)) * 2 + x1 + 1;
                for (let y = y1; y <= y2; y++) {
                    maze[y][wallX] = 1;
                }
                recursiveDivision(x1, y1, wallX, y2, true);
                recursiveDivision(wallX + 1, y1, x2, y2, true);
            }
        }
    }

    function solveMaze() {
        startNode = { x: 0, y: 0 };
        endNode = { x: cols - 1, y: rows - 1 };
        openSet.push(startNode);

        while (openSet.length > 0) {
            let current = openSet.reduce((prev, curr) => prev.f < curr.f ? prev : curr);
            if (current.x === endNode.x && current.y === endNode.y) {
                let path = [];
                let temp = current;
                while (temp.parent) {
                    path.unshift(temp);
                    temp = temp.parent;
                }
                path.forEach(node => {
                    maze[node.y][node.x] = 2;
                    drawMaze();
                    requestAnimationFrame(() => {
                        maze[node.y][node.x] = 3;
                        drawMaze();
                    });
                });
                break;
            }

            openSet = openSet.filter(node => node !== current);
            closedSet.push(current);

            let neighbors = getNeighbors(current);
            neighbors.forEach(neighbor => {
                if (!closedSet.includes(neighbor)) {
                    neighbor.g = current.g + 1;
                    neighbor.h = Math.abs(neighbor.x - endNode.x) + Math.abs(neighbor.y - endNode.y);
                    neighbor.f = neighbor.g + neighbor.h;
                    neighbor.parent = current;
                    if (!openSet.includes(neighbor)) {
                        openSet.push(neighbor);
                    }
                }
            });

            maze[current.y][current.x] = 4;
            drawMaze();
            requestAnimationFrame(() => {
                maze[current.y][current.x] = 5;
                drawMaze();
            });
        }
    }

    function getNeighbors(node) {
        let neighbors = [];
        let directions = [
            { x: 0, y: -1 },
            { x: 0, y: 1 },
            { x: -1, y: 0 },
            { x: 1, y: 0 }
        ];
        directions.forEach(dir => {
            let newX = node.x + dir.x;
            let newY = node.y + dir.y;
            if (newX >= 0 && newX < cols && newY >= 0 && newY < rows && maze[newY][newX] !== 1) {
                neighbors.push({ x: newX, y: newY });
            }
        });
        return neighbors;
    }

    recursiveDivision(0, 0, cols - 1, rows - 1, true);
    drawMaze();
    requestAnimationFrame(solveMaze);
}
